examples.Python:
devices = Audio.get_output_devices()
for device in devices:
    rustic.log("info", device["id"] + ": " + device["name"])

examples.C++:
auto devices = Audio::get_output_devices();
for (const auto &device : devices.array()) {
  rustic.log("info", device.at("id").string() + ": " + device.at("name").string());
}

examples.C#:
var devices = Audio.get_output_devices();
foreach (var device in devices.EnumerateArray()) {
  rustic.log("info", device.GetProperty("id").GetString() + ": " + device.GetProperty("name").GetString());
}

examples.C:
RusticAudioDevices devices = Audio.get_output_devices();
for (size_t i = 0; i < devices.count; ++i) {
  rustic.log("info", devices.items[i].name);
}

examples.Java:
var devices = (java.util.List<?>)Audio.get_output_devices();
for (var item : devices) {
  var device = (java.util.Map<?, ?>)item;
  rustic.log("info", device.get("id") + ": " + device.get("name"));
}

